// bundle/app.js — embed a query + a corpus, then nearest-neighbour rank.
//
// Persist `_meta.alias` + `_meta.dimensions` alongside every cached vector.
// If a later registry change rotates the default alias, an alias mismatch
// is your cue to re-embed instead of silently mixing dimensions.
async function embedAll(texts) {
  const reply = await anna.llm.embed({ input: texts /*, model: "anna-managed-v1" */ });
  return {
    alias: reply.model,
    dimensions: reply._meta.dimensions,
    vectors: reply.data.sort((a, b) => a.index - b.index).map((d) => d.embedding),
    usage: reply.usage,
  };
}

function cosine(a, b) {
  let dot = 0;
  for (let i = 0; i < a.length; i++) dot += a[i] * b[i];
  return dot; // both vectors L2-normalised by provider
}

try {
  const corpus = ["Anna runs apps", "Cats nap a lot", "Embeddings are dense vectors"];
  const { vectors: docVecs, alias, dimensions } = await embedAll(corpus);

  const { vectors: [qVec] } = await embedAll(["how do anna apps work?"]);

  const ranked = corpus
    .map((text, i) => ({ text, score: cosine(qVec, docVecs[i]) }))
    .sort((a, b) => b.score - a.score);

  console.log(`Top match (${alias}, dim=${dimensions}):`, ranked[0]);
} catch (e) {
  switch (e.code) {
    case "APP_NOT_GRANTED":      setStatus("User has not granted embed access to this app"); break;
    case "APP_INVALID_REQUEST":  setStatus(`Bad request: ${e.message}`);                     break;
    case "APP_PROVIDER_ERROR":   setStatus("Embedding provider error — please retry");       break;
    case "APP_SESSION_REVOKED":  resetAndRetry();                                             break;
    default:                     throw e;
  }
}
